23	import java.util.Optional;
24	import org.springframework.stereotype.Service;
25	
26	@Service
27	public class ResumoCompraService {
28	
29	    private final RegistroOpcoesEntrega registroOpcoesEntrega;
30	    private final RegistroCupons registroCupons;
31	    private final RegistroNiveisClube registroNiveisClube;
32	    private final RegistroFormasPagamento registroFormasPagamento;
33	
34	    public ResumoCompraService(
35	            RegistroOpcoesEntrega registroOpcoesEntrega,
36	            RegistroCupons registroCupons,
37	            RegistroNiveisClube registroNiveisClube,
38	            RegistroFormasPagamento registroFormasPagamento) {
39	        this.registroOpcoesEntrega = registroOpcoesEntrega;
40	        this.registroCupons = registroCupons;
41	        this.registroNiveisClube = registroNiveisClube;
42	        this.registroFormasPagamento = registroFormasPagamento;
43	    }
44	
45	    public ResumoResponseDTO calcular(ResumoRequestDTO request) {
46	        List<Item> itens = validarItens(request.itens());
47	        BigDecimal subtotalProdutos = Arredondamento.paraCentavos(somarSubtotal(itens));
48	        BigDecimal pesoTotal = somarPeso(itens);
49	
50	        NivelClube nivel = validarNivelClube(request.nivelClube());
51	        Regiao regiao = validarRegiao(request.regiao());
52	        OpcaoEntrega opcaoEntrega = validarModalidade(request.modalidadeEntrega(), pesoTotal);
53	
54	        Optional<Cupom> cupom = validarCupom(request.cupom(), itens, subtotalProdutos);
55	
56	        int parcelas = request.parcelas() == null ? 1 : request.parcelas();
57	        CalculoPagamento calculoPagamento = validarFormaPagamento(request.formaPagamento());
58	        if (!calculoPagamento.parcelaPermitida(parcelas)) {
59	            throw new CheckoutException(ErroCodigo.PARCELAMENTO_INVALIDO);
60	        }
61	
62	        BigDecimal freteBase = Arredondamento.paraCentavos(opcaoEntrega.custo(pesoTotal));
63	        BigDecimal freteExibido = nivel.freteGratis() ? BigDecimal.ZERO.setScale(2) : freteBase;
64	
65	        BigDecimal seguro = Arredondamento.paraCentavos(subtotalProdutos.multiply(regiao.percentualSeguro()));
66	
67	        BigDecimal descontoCupom = cupom
68	                .map(c -> Arredondamento.paraCentavos(c.desconto(itens, subtotalProdutos, freteExibido)))
69	                .orElse(BigDecimal.ZERO.setScale(2));
70	
71	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(freteExibido).add(seguro);
72	
73	        if (!calculoPagamento.disponivel(totalPedido)) {
74	            throw new CheckoutException(ErroCodigo.FORMA_PAGAMENTO_INDISPONIVEL);
75	        }
76	
77	        ResultadoPagamento resultadoPagamento = calculoPagamento.calcular(totalPedido, parcelas);
78	
79	        BigDecimal creditoProximaCompra = Arredondamento.paraCentavos(
80	                subtotalProdutos.multiply(nivel.percentualCredito()));
81	        boolean brinde = nivel.elegivelBrinde(subtotalProdutos);
82	
83	        return new ResumoResponseDTO(
84	                subtotalProdutos,
85	                descontoCupom,
86	                freteExibido,
87	                opcaoEntrega.prazoDias(),
88	                seguro,
89	                resultadoPagamento.ajuste(),
90	                resultadoPagamento.totalFinal(),
91	                parcelas,
92	                resultadoPagamento.valorParcela(),
93	                creditoProximaCompra,
94	                brinde);
95	    }
96	
97	    private List<Item> validarItens(List<ItemRequestDTO> itensRequest) {
98	        if (itensRequest == null || itensRequest.isEmpty()) {
99	            throw new CheckoutException(ErroCodigo.PEDIDO_INVALIDO);
100	        }
101	        List<Item> itens = itensRequest.stream()
102	                .map(dto -> new Item(
103	                        dto.nome(),
104	                        dto.precoUnitario(),
105	                        dto.quantidade() == null ? 0 : dto.quantidade(),
106	                        dto.pesoKg()))
107	                .toList();
108	        boolean todosValidos = itens.stream().allMatch(Item::valido);
109	        if (!todosValidos) {
110	            throw new CheckoutException(ErroCodigo.PEDIDO_INVALIDO);
111	        }
112	        return itens;
113	    }
114	
115	    private BigDecimal somarSubtotal(List<Item> itens) {
116	        return itens.stream().map(Item::subtotal).reduce(BigDecimal.ZERO, BigDecimal::add);
117	    }
118	
119	    private BigDecimal somarPeso(List<Item> itens) {
120	        return itens.stream().map(Item::peso).reduce(BigDecimal.ZERO, BigDecimal::add);
121	    }
122	
123	    private NivelClube validarNivelClube(String codigo) {
124	        if (codigo == null) {
125	            throw new CheckoutException(ErroCodigo.NIVEL_CLUBE_INVALIDO);
126	        }
127	        return registroNiveisClube.buscar(codigo)
128	                .orElseThrow(() -> new CheckoutException(ErroCodigo.NIVEL_CLUBE_INVALIDO));
129	    }
130	
131	    private Regiao validarRegiao(String codigo) {
132	        if (codigo == null) {
133	            throw new CheckoutException(ErroCodigo.REGIAO_INVALIDA);
134	        }
135	        try {
136	            return Regiao.valueOf(codigo);
137	        } catch (IllegalArgumentException e) {
138	            throw new CheckoutException(ErroCodigo.REGIAO_INVALIDA);
139	        }
140	    }
141	
142	    private OpcaoEntrega validarModalidade(String codigo, BigDecimal pesoTotal) {
143	        if (codigo == null) {
144	            throw new CheckoutException(ErroCodigo.MODALIDADE_INVALIDA);
145	        }
146	        OpcaoEntrega opcaoEntrega = registroOpcoesEntrega.buscar(codigo)
147	                .orElseThrow(() -> new CheckoutException(ErroCodigo.MODALIDADE_INVALIDA));
148	        if (!opcaoEntrega.disponivel(pesoTotal)) {
149	            throw new CheckoutException(ErroCodigo.MODALIDADE_INDISPONIVEL);
150	        }
151	        return opcaoEntrega;
152	    }
153	
154	    private Optional<Cupom> validarCupom(String codigo, List<Item> itens, BigDecimal subtotalProdutos) {
155	        if (codigo == null) {
156	            return Optional.empty();
157	        }
158	        Cupom cupom = registroCupons.buscar(codigo)
159	                .orElseThrow(() -> new CheckoutException(ErroCodigo.CUPOM_INVALIDO));
160	        if (!cupom.aplicavel(itens, subtotalProdutos)) {
161	            throw new CheckoutException(ErroCodigo.CUPOM_NAO_APLICAVEL);
162	        }
163	        return Optional.of(cupom);
164	    }
165	
166	    private CalculoPagamento validarFormaPagamento(String codigo) {
167	        if (codigo == null) {
168	            throw new CheckoutException(ErroCodigo.FORMA_PAGAMENTO_INVALIDA);
169	        }
170	        try {
171	            FormaPagamento.valueOf(codigo);
172	        } catch (IllegalArgumentException e) {
173	            throw new CheckoutException(ErroCodigo.FORMA_PAGAMENTO_INVALIDA);
174	        }
175	        return registroFormasPagamento.buscar(codigo)
176	                .orElseThrow(() -> new CheckoutException(ErroCodigo.FORMA_PAGAMENTO_INVALIDA));
177	    }
178	}
