1	package com.loja.checkout.dominio.pagamento;
2	
3	import com.loja.checkout.util.Arredondamento;
4	import java.math.BigDecimal;
5	import java.math.RoundingMode;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	public class Cartao implements CalculoPagamento {
10	
11	    private static final int PARCELAS_SEM_JUROS = 3;
12	    private static final int MAXIMO_PARCELAS = 12;
13	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
14	    private static final int ESCALA_INTERMEDIARIA = 20;
15	
16	    @Override
17	    public FormaPagamento forma() {
18	        return FormaPagamento.CARTAO;
19	    }
20	
21	    @Override
22	    public boolean parcelaPermitida(int parcelas) {
23	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
24	    }
25	
26	    @Override
27	    public boolean disponivel(BigDecimal totalPedido) {
28	        return true;
29	    }
30	
31	    @Override
32	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
33	        if (parcelas <= PARCELAS_SEM_JUROS) {
34	            BigDecimal valorParcela = Arredondamento.paraCentavos(
35	                    totalPedido.divide(BigDecimal.valueOf(parcelas), ESCALA_INTERMEDIARIA, RoundingMode.HALF_EVEN));
36	            return new ResultadoPagamento(BigDecimal.ZERO.setScale(2), totalPedido, valorParcela);
37	        }
38	
39	        BigDecimal potencia = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
40	        BigDecimal numerador = totalPedido.multiply(TAXA_MENSAL).multiply(potencia);
41	        BigDecimal denominador = potencia.subtract(BigDecimal.ONE);
42	        BigDecimal valorParcela = Arredondamento.paraCentavos(
43	                numerador.divide(denominador, ESCALA_INTERMEDIARIA, RoundingMode.HALF_EVEN));
44	        BigDecimal totalFinal = Arredondamento.paraCentavos(valorParcela.multiply(BigDecimal.valueOf(parcelas)));
45	        BigDecimal ajuste = totalFinal.subtract(totalPedido);
46	        return new ResultadoPagamento(ajuste, totalFinal, valorParcela);
47	    }
48	}
