package com.loja.checkout.dominio.pagamento;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;
import java.util.stream.Collectors;
import org.springframework.stereotype.Component;

@Component
public class RegistroFormasPagamento {

    private final Map<FormaPagamento, CalculoPagamento> calculosPorForma;

    public RegistroFormasPagamento(List<CalculoPagamento> calculos) {
        this.calculosPorForma = calculos.stream()
                .collect(Collectors.toUnmodifiableMap(CalculoPagamento::forma, Function.identity()));
    }

    public Optional<CalculoPagamento> buscar(String codigo) {
        return Arrays.stream(FormaPagamento.values())
                .filter(forma -> forma.name().equals(codigo))
                .findFirst()
                .map(calculosPorForma::get);
    }
}

