class CheckoutControllerTest {

    @Autowired
    private TestRestTemplate restTemplate;

    private HttpEntity<String> requisicao(String corpoJson) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        return new HttpEntity<>(corpoJson, headers);
    }

    @Test
    void resumoComPedidoValidoDevolveCamposEmCamelCaseComDuasCasasDecimais() {
        String corpo = """
                {
                  "itens": [
                    {"nome": "Camiseta", "precoUnitario": 79.90, "quantidade": 2, "pesoKg": 0.30},
                    {"nome": "Tenis", "precoUnitario": 249.90, "quantidade": 1, "pesoKg": 1.20}
                  ],
                  "modalidadeEntrega": "EXPRESSA",
                  "cupom": "BEMVINDO10",
                  "formaPagamento": "PIX",
                  "nivelClube": "BRONZE",
                  "regiao": "NORTE"
                }
                """;

        ResponseEntity<String> resposta =
                restTemplate.postForEntity("/checkout/resumo", requisicao(corpo), String.class);

