                .contains("\"subtotalProdutos\":409.70")
                .contains("\"descontoCupom\":40.97")
                .contains("\"frete\":33.10")
                .contains("\"prazoEntregaDias\":2")
                .contains("\"seguro\":10.24")
                .contains("\"ajustePagamento\":-20.60")
                .contains("\"totalFinal\":391.47")
