                  "itens": [],
                  "modalidadeEntrega": "ECONOMICA",
                  "formaPagamento": "PIX",
                  "nivelClube": "BRONZE",
                  "regiao": "SUDESTE"
                }
                """;

        ResponseEntity<String> resposta =
                restTemplate.postForEntity("/checkout/resumo", requisicao(corpo), String.class);

        assertThat(resposta.getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
        assertThat(resposta.getBody()).isEqualTo("{\"erro\":\"PEDIDO_INVALIDO\"}");
    }
}

